    modal(`<div class="modal-heading"><div><div class="eyebrow">${editing?'EDIT TEMPLATE':'NEW TEMPLATE'}</div><h2>${editing?'Edit message template':'Create message template'}</h2></div><button class="icon-button" data-close>×</button></div><form id="message-template-form"><label>Template name<input name="name" maxlength="80" required value="${esc(item?.name||'')}"></label><label>Minecraft console command<textarea name="body" class="editor-area" required maxlength="4096" placeholder="say {{server_name}} maintenance starts in {{minutes}} minutes">${esc(item?.body||'')}</textarea><small>One line, with optional placeholders {{server_name}}, {{minutes}}, and {{seconds}}. Custom templates are available in Minecraft schedules.</small></label><div class="modal-actions"><button type="button" class="button subtle" data-close>Cancel</button><button class="button primary">${editing?'Save template':'Create template'}</button></div></form>`);
